package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for Option.clone()
 */
class OptionCloneTest {

    /**
     * A concrete subclass of Option that implements Cloneable so that Object.clone()
     * will succeed for instances of this runtime type.
     */
    static class CloneableOption extends Option implements Cloneable {
        CloneableOption(String opt, String description) {
            super(opt, description);
        }
    }

    @Test
    void testCloneSuccessfulCreatesDistinctDeepCopiedValuesList() throws Exception {
        // create an instance whose runtime class implements Cloneable
        CloneableOption original = new CloneableOption("o", "desc");

        // use reflection to set the private 'values' field to a mutable list with elements
        Field valuesField = Option.class.getDeclaredField("values");
        valuesField.setAccessible(true);
        List<String> initialValues = new ArrayList<>(Arrays.asList("one", "two"));
        valuesField.set(original, initialValues);

        // perform clone (Option.clone() is public)
        Object clonedObj = original.clone();
        assertNotNull(clonedObj, "clone() should not return null");
        assertTrue(clonedObj instanceof Option, "clone() should return an Option");
        Option cloned = (Option) clonedObj;

        // cloned instance should be a different object
        assertNotSame(original, cloned, "clone should produce a different instance");

        // obtain values lists from both original and clone via reflection
        @SuppressWarnings("unchecked")
        List<String> originalValues = (List<String>) valuesField.get(original);
        @SuppressWarnings("unchecked")
        List<String> clonedValues = (List<String>) valuesField.get(cloned);

        // contents should be equal initially
        assertEquals(originalValues, clonedValues, "values content should be equal after cloning");

        // but the lists themselves must be distinct objects (deep copy of the list)
        assertNotSame(originalValues, clonedValues, "values list should be a distinct object in the clone");

        // mutating the original list must not affect the clone's list
        originalValues.add("three");
        assertTrue(originalValues.contains("three"));
        assertFalse(clonedValues.contains("three"), "modification to original's values should not affect clone's values");

        // mutating the clone's list must not affect the original's list
        clonedValues.add("four");
        assertTrue(clonedValues.contains("four"));
        assertFalse(originalValues.contains("four"), "modification to clone's values should not affect original's values");
    }

    @Test
    void testCloneUnsupportedWhenNotCloneable() {
        // create an Option instance whose runtime class does NOT implement Cloneable
        Option notCloneable = new Option("x", "desc");

        UnsupportedOperationException ex = assertThrows(UnsupportedOperationException.class, notCloneable::clone,
                "clone() on a non-Cloneable runtime type should throw UnsupportedOperationException");

        // ensure the underlying cause is a CloneNotSupportedException
        assertNotNull(ex.getCause(), "UnsupportedOperationException should have a cause");
        assertTrue(ex.getCause() instanceof CloneNotSupportedException,
                "the cause of the UnsupportedOperationException should be CloneNotSupportedException");
    }
}

